#!/usr/bin/env node
/**
 * Derive Open Graph / Twitter card metadata for every routed Site B page.
 *
 * WHY THIS IS DERIVED AND NOT HAND-AUTHORED. og:title, og:description and
 * og:url are restatements of three fields the pages already carry: <title>,
 * <meta name="description"> and <link rel="canonical">. Hand-authoring them
 * would be a second source of truth for each, and this repo already knows how
 * that ends — the cover tile said "20 terms" against a 28-term file.
 *
 * It matters more here than anywhere else in the site, because three of the
 * eleven pages are GENERATED by cloning part-6's shell. The generators rewrite
 * title, canonical and description with their own targeted replaces, and the
 * og tags restate those three. Hand-authoring an og:title into part-6 would stamp
 * Part 6's identity onto glossary, framework-in-math and framework-in-pictures
 * — silently, and only visible when someone shared the link. Deriving after
 * the generators run means the clone can't carry the donor's identity. The
 * generators also stamp their own page with the same function
 * (scripts/social-meta.mjs) before writing, so even a generator run on its own
 * never leaves a page sharing as Part 6.
 *
 * Ordering therefore matters: this MUST run after build:glossary /
 * build:pictures / build:math in prebuild, and it re-reads from disk.
 *
 * The block it writes is delimited and rewritten wholesale on every run, so
 * running twice is a no-op and an edited block is corrected rather than
 * duplicated.
 *
 * Run:   npm run build:social-meta
 * Check: npm run audit:social      (no browser, safe in any pipeline)
 */
import fs from 'node:fs';
import path from 'node:path';
import { PAGES, THEMES, CARD_THEME, CARD_DIR, cardFile } from './social-cards.config.mjs';
import { decodeEntities, descriptionProblems, shareText } from './site-titles.mjs';
import { headFields, stampSocialMeta } from './social-meta.mjs';

const ROOT = path.resolve(import.meta.dirname, '..');
const SITE = path.join(ROOT, 'public', 'site-b');
const CARDS = path.join(ROOT, ...CARD_DIR);
const MANIFEST = path.join(CARDS, 'cards.json');
const CHECK = process.argv.includes('--check');

function readPage(page) {
  const file = path.join(SITE, `${page}.html`);
  const html = fs.readFileSync(file, 'utf8');
  return { file, html, ...headFields(html, page) };
}

const problems = [];
let written = 0;

for (const page of PAGES) {
  const meta = readPage(page);
  // A description is part of what a share shows, so it is held to D-TITLES
  // here, where it is copied into og and twitter: 115 characters at most, no
  // em dash, and not a restatement of the title.
  for (const why of descriptionProblems(decodeEntities(meta.description), shareText(decodeEntities(meta.title)))) {
    problems.push(`${page}: meta ${why}`);
  }
  let next;
  try { next = stampSocialMeta(meta.html, page); } catch (err) { problems.push(err.message); continue; }

  if (CHECK) {
    if (next !== meta.html) problems.push(`${page}: social meta is stale — run \`npm run build:social-meta\``);
  } else if (next !== meta.html) {
    fs.writeFileSync(meta.file, next);
    written += 1;
  }
}

// Card drift: a card bakes the page title into pixels, so a title edit silently
// invalidates the art. The manifest records what each card was rendered from;
// comparing it to the live title catches that without needing to read a PNG.
if (fs.existsSync(MANIFEST)) {
  const manifest = JSON.parse(fs.readFileSync(MANIFEST, 'utf8'));
  for (const [page, recorded] of Object.entries(manifest.cards || {})) {
    if (!PAGES.includes(page)) { problems.push(`card manifest lists unknown page "${page}"`); continue; }
    const live = readPage(page).title;
    for (const theme of Object.keys(THEMES)) {
      // Both appearances are checked, not just the served one: an unserved
      // card that silently went missing would only surface later, at the
      // moment someone flipped CARD_THEME and had no art to flip to.
      if (!fs.existsSync(path.join(CARDS, cardFile(page, theme)))) {
        problems.push(`${page}: no ${theme} card art — run \`npm run build:social-cards\``);
      }
    }
    if (live !== recorded.title) {
      problems.push(`${page}: card art was rendered from a different title. Re-run \`npm run build:social-cards\`\n      card: ${recorded.title}\n      page: ${live}`);
    }
    // The card sets the description too, so a re-described page outruns its art
    // exactly as a retitled one does (x-visuals#20).
    const liveDescription = readPage(page).description;
    if (liveDescription !== recorded.description) {
      problems.push(`${page}: card art was rendered from a different description. Re-run \`npm run build:social-cards\`\n      card: ${recorded.description}\n      page: ${liveDescription}`);
    }
  }
} else if (CHECK) {
  problems.push('no card manifest at public/site-b/brand/social/cards.json — run `npm run build:social-cards`');
}

if (problems.length) {
  console.error(`Social meta ${CHECK ? 'audit' : 'build'} failed:\n  - ${problems.join('\n  - ')}`);
  process.exit(1);
}

console.log(CHECK
  ? `Social audit passed: ${PAGES.length} pages carry derived og/twitter metadata; ${Object.keys(THEMES).length} appearances present for each, serving "${CARD_THEME}"; every card matches its page title and description.`
  : `Social meta built: ${PAGES.length} pages checked, ${written} updated.`);
